function smallestMirrorWord(s: string): string {
  const a = s.split("");
  for (let i = 0, j = a.length - 1; i < j; i++, j--) {
    const m = a[i] < a[j] ? a[i] : a[j];
    a[i] = m;
    a[j] = m;
  }
  return a.join("");
}

