class Solution:
    def smallestMirrorWord(self, s: str) -> str:
        a = list(s)
        i, j = 0, len(a) - 1
        while i < j:
            a[i] = a[j] = min(a[i], a[j])
            i += 1
            j -= 1
        return "".join(a)

