function smallestMirrorWord(s: string): string {
  const n = s.length;
  const half: string[] = [];
  for (let i = 0; i < Math.floor(n / 2); i++) {
    const x = s[i], y = s[n - 1 - i];
    half.push(x < y ? x : y);
  }
  const mid = n % 2 === 1 ? s[Math.floor(n / 2)] : "";
  return half.join("") + mid + half.reverse().join("");
}

